package com.soumya.walletwise.auth;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.beans.factory.annotation.*; import org.springframework.http.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.*; import java.util.*;
@RestController @RequestMapping("/auth") @CrossOrigin(origins="*") public class AuthController { final UserRepository users; final BCryptPasswordEncoder bcrypt=new BCryptPasswordEncoder(); final Jwt jwt; AuthController(UserRepository u,@Value("${walletwise.jwt.secret}")String s,@Value("${walletwise.jwt.expiration-seconds}")long e){users=u;jwt=new Jwt(s,e);} record Credentials(@NotBlank @Email String email,@NotBlank @Size(min=8) String password,@NotBlank String name){} record Login(@NotBlank @Email String email,@NotBlank String password){} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) Map<String,Object> register(@Valid @RequestBody Credentials c){String e=c.email().toLowerCase();if(users.existsByEmail(e))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");User u=new User();u.email=e;u.name=c.name();u.passwordHash=bcrypt.encode(c.password());users.save(u);return result(u);} @PostMapping("/login") Map<String,Object> login(@Valid @RequestBody Login l){User u=users.findByEmail(l.email().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));if(!bcrypt.matches(l.password(),u.passwordHash))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");return result(u);} @GetMapping("/health") Map<String,Object> health(){return Map.of("status","UP","service","auth-service");} private Map<String,Object> result(User u){return Map.of("token",jwt.issue(u),"tokenType","Bearer","user",Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role));}}
